%% rp_data_tool.m
% FSAE Datenanalyse-Tool — Racing Performance Electrical
% Kompatibilitaet: MATLAB R2023b+
%
% Autor:  [Benutzer]
% Datum:  2026-06-24
% Changelog:
%   2026-06-24  Refactoring nach internem Coding-Standard:
%               - Modulare Struktur mit Packages (+config, +io, +signal, etc.)
%               - +RP Plot-Design Integration
%               - Neue Tabs: Bremse-Balance, Efficiency-Map, Compare
%               - INS Dead-Reckoning Fix (cumtrapz, alpha konfigurierbar)
%               - Energieberechnung via trapz
%
% Eingabe:  Keine (Dateiauswahl per Dialog)
% Ausgabe:  uifigure mit Analyse-Tabs

function rp_data_tool()
%% Initialisierung
clc;
cfg = get_config();

fprintf('============================================\n');
fprintf('  RP FSAE Datenanalyse-Tool\n');
fprintf('  Racing Performance — Electrical\n');
fprintf('============================================\n\n');

%% Dateiauswahl
[datei_name, datei_pfad] = uigetfile('*.mf4;*.MF4', 'MDF4 Datei auswaehlen');
if isequal(datei_name, 0)
    fprintf('Kein File gewaehlt. Tool wird beendet.\n');
    return;
end
datei_pfad_voll = fullfile(datei_pfad, datei_name);

% % Log gehardcoded zum schnelleren Debuggen
% datei_name = 'RP25e_2025-09-13_10-37-50_SattlerAccel_Italy.mf4';
% datei_pfad_voll = 'C:\Users\Danie\OneDrive\Desktop\RP26_Data_Analysis\Logging_data\Accels\RP25e_2025-09-13_10-37-50_SattlerAccel_Italy.mf4';
% fprintf('Lade: %s\n', datei_pfad_voll);

%% Laden & Validierung
roh_daten = lade_mdf4(datei_pfad_voll, cfg);

%% Metadaten
meta = parse_dateiname(datei_name, cfg);

%% Signalextraktion
fprintf('Extrahiere Signale...\n');
signale = extrahiere_signale(roh_daten, cfg);
fprintf('Signalextraktion abgeschlossen.\n\n');

%% Abgeleitete Groessen
signale = berechne_abgeleitete(signale, cfg);

%% GUI
erstelle_gui(signale, meta, datei_pfad_voll, cfg);
end

function [wert_label, signal_info] = build_tab_alle_signale(tab, signale, cfg)
%BUILD_TAB_ALLE_SIGNALE Erstellt den Tab mit allen Signalwerten.
%
%   Eingabe:
%       tab     — ui.Tab Objekt
%       signale — Struct mit extrahierten Signalen
%       cfg     — Config-Struct
%
%   Ausgabe:
%       wert_label  — Array von uilabel-Handles (fuer Live-Updates)
%       signal_info — Cell-Array mit {feldname, ok_feldname} pro Zeile
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24
%   Changelog:
%       2026-06-24  Schleifenabbruch korrigiert, vertcat-Fix

    C = farben();

    TAB_W = 1590;
    TAB_H = 855;
    N_COLS = cfg.layout.spalten_signale;
    RH = cfg.layout.zeilen_hoehe_signale;
    SH = cfg.layout.sektions_hoehe_signale;
    FS_SIG = cfg.layout.schrift.signal;
    FS_HDR = cfg.layout.schrift.header;

    col_w = floor(TAB_W / N_COLS);
    val_w = 70;
    nm_w = col_w - val_w - 18;

    eintraege = build_flat_signal_list(cfg);
    n_eintraege = numel(eintraege);
    pro_spalte = ceil(n_eintraege / N_COLS);

    % Zeitstempel-Label oben
    uilabel(tab, ...
        'Position', [6, TAB_H - 16, 500, 14], ...
        'Text', '● letzter Wert  —  Snapshot-Zeit ueber Topbar setzen', ...
        'FontSize', 7.5, ...
        'FontColor', [0.45, 0.45, 0.45], ...
        'BackgroundColor', 'none');

    wert_label = gobjects(0);
    signal_info = {};

    for ci = 1:N_COLS
        x0 = 2 + (ci - 1) * col_w;
        y_top = TAB_H - 20;

        idx_from = (ci - 1) * pro_spalte + 1;
        idx_to = min(ci * pro_spalte, n_eintraege);

        for ei = idx_from:idx_to
            e = eintraege{ei};

            % Sektions-Header
            if isstruct(e)
                y_top = y_top - SH;
                if y_top < 2
                    break;
                end
                uilabel(tab, ...
                    'Position', [x0, y_top, col_w - 3, SH - 1], ...
                    'Text', ['  ', upper(e.header)], ...
                    'FontSize', FS_HDR, ...
                    'FontWeight', 'bold', ...
                    'FontColor', C.orange, ...
                    'BackgroundColor', [0.11, 0.09, 0.06], ...
                    'Interpreter', 'none');
                continue;
            end

            % Signal-Zeile
            y_top = y_top - RH;
            if y_top < 2
                break;
            end

            if iscell(e)
                fn = e{1};
                label = e{2};
                ok_fn = e{3};
            else
                fn =signal_zu_feldname(e);
                ok_fn = [fn, '_ok'];
                label = strrep(strrep(e, '_can', ''), '_', ' ');
                if numel(label) > 38
                    label = [label(1:36), char(8230)]; % % echte Ellipse
                end
            end

            [v, fc] =signal_wert_zu_zeitpunkt(signale, fn, ok_fn, []);

            uilabel(tab, ...
                'Position', [x0 + 1, y_top, 9, RH], ...
                'Text', '●', ...
                'FontSize', 5.5, ...
                'FontColor', fc, ...
                'BackgroundColor', 'none');

            uilabel(tab, ...
                'Position', [x0 + 10, y_top, nm_w, RH], ...
                'Text', label, ...
                'FontSize', FS_SIG, ...
                'FontColor', [0.82, 0.82, 0.82], ...
                'BackgroundColor', 'none', ...
                'Interpreter', 'none');

            lh = uilabel(tab, ...
                'Position', [x0 + col_w - val_w - 4, y_top, val_w, RH], ...
                'Text', v, ...
                'FontSize', FS_SIG, ...
                'FontWeight', 'bold', ...
                'FontColor', fc, ...
                'BackgroundColor', 'none', ...
                'HorizontalAlignment', 'right', ...
                'Interpreter', 'none');

            wert_label(end + 1) = lh;
            signal_info{end + 1} = {fn, ok_fn};
        end

        if y_top < 2
            break;
        end
    end

    % FIX: Sichere vertcat mit Cell-Arrays
    if isempty(signal_info)
        signal_info = {{'__time__', ''}};
    else
        signal_info = signal_info(:);
    end
end

function [wert_str, farbe] = signal_wert_zu_zeitpunkt(signale, fn, ok_fn, zeitpunkt)
%SIGNAL_WERT_ZU_ZEITPUNKT Gibt den Wert eines Signals als String zurueck.
%
%   Eingabe:
%       signale   — Struct mit Signalen
%       fn        — Feldname des Signals
%       ok_fn     — Feldname des OK-Flags
%       zeitpunkt — Zeitpunkt fuer Interpolation (leer = letzter Wert)
%
%   Ausgabe:
%       wert_str — Formatierter Wert oder '--'
%       farbe    — RGB-Farbe (OK=weiss, nicht OK=grau, Fehler=rot)
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24

C = farben();
wert_str = '--';
farbe = C.grau3;

% OK-Flag pruefen
if ~isempty(ok_fn) && isfield(signale, ok_fn)
    if ~signale.(ok_fn)
        return;
    end
end

if ~isfield(signale, fn)
    return;
end

try
    daten =extrahiere_rohdaten(signale.(fn));

    if isempty(daten)
        return;
    end

    if isnumeric(daten)
        if isempty(zeitpunkt)
            % Letzten gueltigen Wert
            gueltig = find(~isnan(daten), 1, 'last');
            if isempty(gueltig)
                return;
            end
            wert = daten(gueltig);
        else
            % Interpolation am Zeitpunkt (falls timeseries)
            if isa(signale.(fn), 'timeseries')
                wert = interp1(signale.(fn).Time, daten, zeitpunkt, 'linear', 'extrap');
            else
                wert = daten(end);
            end
        end

        % Formatierung
        if abs(wert) >= 1000
            wert_str = sprintf('%.1f', wert);
        elseif abs(wert) >= 10
            wert_str = sprintf('%.2f', wert);
        elseif abs(wert) >= 1
            wert_str = sprintf('%.3f', wert);
        else
            wert_str = sprintf('%.4f', wert);
        end

        farbe = C.weiss;
    elseif islogical(daten)
        if daten(end)
            wert_str = '1';
            farbe = C.gruen;
        else
            wert_str = '0';
            farbe = C.rp_rot;
        end
    else
        wert_str = char(daten(end));
        farbe = C.weiss;
    end

catch
    wert_str = 'ERR';
    farbe = C.rp_rot;
end
end

function build_tab_batterie(tab, signale, cfg)
% Autor: [Benutzer]
% Datum: 2026-06-24

C = cfg.farben;
fn_V = signal_zu_feldname('ams_overall_voltage_can');
fn_I = signal_zu_feldname('IVT_Result_I_can');
fn_mn = signal_zu_feldname('ams_cell_min_voltage_can');
fn_mx = signal_zu_feldname('ams_cell_max_voltage_can');
fn_Tm = signal_zu_feldname('ams_cell_max_temp_can');
fn_soc = signal_zu_feldname('ams_capacity_fl_can');

kpis = {
    'Gesamtspannung', letzter_wert(signale, fn_V, '--'), 'V';
    'SoC', letzter_wert(signale, fn_soc, '--'), '%';
    'Strom (IVT)', letzter_wert(signale, fn_I, '--'), 'A';
    'V cell min', letzter_wert(signale, fn_mn, '--'), 'V';
    'V cell max', letzter_wert(signale, fn_mx, '--'), 'V';
    'T cell max', letzter_wert(signale, fn_Tm, '--'), '°C';
    };
build_kpi_zeile_custom(tab, kpis, cfg, [10, 840, 1560, 80]);

ax1 = erstelle_plot_bereich(tab, [10, 620, 770, 210], 'Spannung & Strom', cfg);
plot_oder_leer(ax1, signale, {'ams_overall_voltage_can', 'IVT_Result_I_can'}, {'V pack (V)', 'I (A)'}, cfg);

ax2 = erstelle_plot_bereich(tab, [10, 400, 770, 210], 'Zelltemperaturen', cfg);
plot_oder_leer(ax2, signale, {'ams_cell_max_temp_can', 'ams_cell_avg_temp_can', 'ams_cell_min_temp_can'}, ...
    {'T max', 'T avg', 'T min'}, cfg);

ax3 = erstelle_plot_bereich(tab, [10, 180, 770, 210], 'AIR Status', cfg);
plot_oder_leer(ax3, signale, {'air_minus_closed_b_can', 'air_plus_closed_b_can', 'precharge_closed_b_can'}, ...
    {'AIR-', 'AIR+', 'Precharge'}, cfg);

ax_hm = erstelle_plot_bereich(tab, [800, 400, 770, 440], 'Zellspannungs-Heatmap (144 Zellen)', cfg);
plot_zellen_heatmap(ax_hm, signale, 'voltage', cfg);

ax_hm2 = erstelle_plot_bereich(tab, [800, 180, 770, 210], 'Zelltemperatur-Heatmap (48 Sensoren)', cfg);
plot_zellen_heatmap(ax_hm2, signale, 'temp', cfg);

build_ams_fehler(tab, signale, cfg, [10, 80, 1560, 90]);
end

function build_tab_bremse_balance(tab, signale, cfg)
    % Detaillierte Bremsanalyse mit Balance-Berechnung
    % Autor: [Benutzer]
    % Datum: 2026-06-24

    C = cfg.farben;
    
    % KPIs
    p_front_max = signal_max_wert(signale, 'pbrake_front_can', '--');
    p_rear_max = signal_max_wert(signale, 'pbrake_rear_can', '--');
    apps_max = signal_max_wert(signale, 'apps_res_can', '--');
    
    kpis = {
        'p front max', p_front_max, 'bar';
        'p rear max', p_rear_max, 'bar';
        'Balance Ø', letzter_wert(signale, signal_zu_feldname('brake_balance_front_can'), '--'), '%';
        'APPS max', apps_max, '%';
    };
    build_kpi_zeile_custom(tab, kpis, cfg, [10, 840, 1560, 80]);

    % Bremsdruck Front/Rear
    ax1 = erstelle_plot_bereich(tab, [10, 620, 770, 210], 'Bremsdruck Front vs. Rear', cfg);
    plot_oder_leer(ax1, signale, {'pbrake_front_can', 'pbrake_rear_can'}, ...
        {'p front (bar)', 'p rear (bar)'}, cfg);

    % Balance ueber Zeit
    ax2 = erstelle_plot_bereich(tab, [800, 620, 770, 210], 'Bremsbalance Front (%)', cfg);
    plot_oder_leer(ax2, signale, {'brake_balance_front_can'}, {'Balance front (%)'}, cfg);

    % p-Vergleich als Scatter (Balance-Diagnose)
    ax3 = erstelle_plot_bereich(tab, [10, 340, 770, 270], 'Bremsdruck-Korrelation Front/Rear', cfg);
    fn_pf = signal_zu_feldname('pbrake_front_can');
    fn_pr = signal_zu_feldname('pbrake_rear_can');
    fn_spd = signal_zu_feldname('speed_can');
    
    if isfield(signale, fn_pf) && signale.([fn_pf '_ok']) && ...
       isfield(signale, fn_pr) && signale.([fn_pr '_ok'])
        try
            pf = signale.(fn_pf);
            pr = sicheres_resample(signale.(fn_pr), pf.Time);
            
            % Nur Bremsphasen (p > 1 bar)
            brems_mask = pf.Data > 1 & pr.Data > 1;
            
            if any(brems_mask)
                pf_b = pf.Data(brems_mask);
                pr_b = pr.Data(brems_mask);
                
                % Farbe nach Geschwindigkeit
                if isfield(signale, fn_spd) && signale.([fn_spd '_ok'])
                    spd = sicheres_resample(signale.(fn_spd), pf.Time);
                    spd_b = spd.Data(brems_mask);
                    scatter(ax3, pf_b, pr_b, 8, spd_b, 'filled', 'MarkerFaceAlpha', 0.6);
                    colormap(ax3, 'hot');
                    cb = colorbar(ax3);
                    cb.Color = C.grau;
                    cb.Label.String = 'Speed (km/h)';
                else
                    scatter(ax3, pf_b, pr_b, 8, 'filled', ...
                        'MarkerFaceColor', C.rot, 'MarkerFaceAlpha', 0.5);
                end
                
                % Ideale Balance-Linie (1:1)
                hold(ax3, 'on');
                p_max = max(max(pf_b), max(pr_b));
                plot(ax3, [0, p_max], [0, p_max], '--', 'Color', C.grau2, 'LineWidth', 1.2, ...
                    'DisplayName', '1:1 Balance');
                hold(ax3, 'off');
                
                xlabel(ax3, 'p front (bar)', 'Color', C.grau, 'FontSize', 8);
                ylabel(ax3, 'p rear (bar)', 'Color', C.grau, 'FontSize', 8);
                axis(ax3, 'equal');
                legend(ax3, 'Location', 'best', 'TextColor', C.grau, ...
                    'Color', [0.13, 0.13, 0.13], 'EdgeColor', C.grau2, 'FontSize', 8);
            else
                markiere_leer(ax3, 'Keine Bremsdaten > 1 bar', cfg);
            end
        catch ME
            markiere_leer(ax3, sprintf('Fehler: %s', ME.message), cfg);
        end
    else
        markiere_leer(ax3, 'Bremsdruck-Daten nicht verfuegbar', cfg);
    end

    % APPS vs. Bremsdruck (Plausibilitaet)
    ax4 = erstelle_plot_bereich(tab, [800, 340, 770, 270], 'APPS vs. Bremsdruck (Plausibilitaet)', cfg);
    fn_apps = signal_zu_feldname('apps_res_can');
    
    if isfield(signale, fn_pf) && signale.([fn_pf '_ok']) && ...
       isfield(signale, fn_apps) && signale.([fn_apps '_ok'])
        try
            apps = sicheres_resample(signale.(fn_apps), pf.Time);
            
            % Farbe nach Zeit fuer Trace-Erkennung
            n_punkte = numel(pf.Data);
            scatter(ax4, apps.Data, pf.Data, 6, pf.Time, 'filled', 'MarkerFaceAlpha', 0.5);
            colormap(ax4, 'parula');
            cb = colorbar(ax4);
            cb.Color = C.grau;
            cb.Label.String = 'Zeit (s)';
            
            xlabel(ax4, 'APPS (%)', 'Color', C.grau, 'FontSize', 8);
            ylabel(ax4, 'p front (bar)', 'Color', C.grau, 'FontSize', 8);
            
            % APPS-Bremsen-Implausibilitaet markieren
            hold(ax4, 'on');
            impl_mask = apps.Data > 25 & pf.Data > 5; % APPS > 25% UND Bremsen > 5 bar
            if any(impl_mask)
                scatter(ax4, apps.Data(impl_mask), pf.Data(impl_mask), 20, ...
                    'MarkerFaceColor', 'none', 'MarkerEdgeColor', C.rot, ...
                    'LineWidth', 1.5, 'DisplayName', 'Implausibilitaet!');
                legend(ax4, 'Location', 'best', 'TextColor', C.grau, ...
                    'Color', [0.13, 0.13, 0.13], 'EdgeColor', C.grau2, 'FontSize', 8);
            end
            hold(ax4, 'off');
        catch ME
            markiere_leer(ax4, sprintf('Fehler: %s', ME.message), cfg);
        end
    else
        markiere_leer(ax4, 'APPS oder Bremsdruck nicht verfuegbar', cfg);
    end

    % Bremsleistung (abschaetzung)
    ax5 = erstelle_plot_bereich(tab, [10, 60, 1560, 270], 'Bremsleistung & Rekuperation', cfg);
    if signale.P_pack_ok
        try
            t = signale.P_pack.Time;
            P = signale.P_pack.Data;
            
            % Bremsleistung = negative Pack-Leistung
            P_bremse = -P .* (P < 0); % [W] nur Rekuperation
            
            % Bremsdruck als Proxy fuer mechanische Bremsleistung
            if isfield(signale, fn_pf) && signale.([fn_pf '_ok'])
                pf_r = sicheres_resample(signale.(fn_pf), t);
                % Annahme: p * konstante = mechanische Bremsleistung (qualitativ)
                P_mech_bremse = pf_r.Data * 100; % [a.u.]
                
                yyaxis(ax5, 'left');
                plot(ax5, t, P_bremse / 1000, 'Color', C.gruen, 'LineWidth', 1.2, ...
                    'DisplayName', 'Rekuperation (kW)');
                ylabel(ax5, 'Rekuperation (kW)', 'Color', C.gruen, 'FontSize', 8);
                ax5.YColor = C.gruen;
                
                yyaxis(ax5, 'right');
                plot(ax5, t, P_mech_bremse, 'Color', C.orange, 'LineWidth', 1.0, ...
                    'DisplayName', 'Bremsdruck proxy (a.u.)');
                ylabel(ax5, 'Bremsdruck proxy (a.u.)', 'Color', C.orange, 'FontSize', 8);
                ax5.YColor = C.orange;
                
                xlabel(ax5, 'Zeit (s)', 'Color', C.grau, 'FontSize', 8);
                legend(ax5, 'Location', 'best', 'TextColor', C.grau, ...
                    'Color', [0.13, 0.13, 0.13], 'EdgeColor', C.grau2, 'FontSize', 8);
            else
                plot(ax5, t, P_bremse / 1000, 'Color', C.gruen, 'LineWidth', 1.2);
                xlabel(ax5, 'Zeit (s)', 'Color', C.grau, 'FontSize', 8);
                ylabel(ax5, 'Rekuperation (kW)', 'Color', C.grau, 'FontSize', 8);
            end
        catch ME
            markiere_leer(ax5, sprintf('Fehler: %s', ME.message), cfg);
        end
    else
        markiere_leer(ax5, 'Pack-Leistung nicht verfuegbar', cfg);
    end
end

function build_tab_compare(tab, signale, cfg)
    % Session-Vergleich mit Zeit-Offset-Steuerung und GPS-Track
    % Autor: [Benutzer]
    % Datum: 2026-06-24

    C = cfg.farben;
    
    % UI fuer zweite Session und Zeit-Offset
    pnl_ctrl = uipanel(tab, 'Position', [10, 840, 1560, 80], ...
        'BackgroundColor', C.panel, 'BorderType', 'line', 'HighlightColor', C.grau2);
    
    uilabel(pnl_ctrl, 'Position', [10, 45, 200, 20], ...
        'Text', 'SESSION VERGLEICH', 'FontSize', 12, 'FontWeight', 'bold', ...
        'FontColor', C.rot, 'BackgroundColor', 'none');
    
    uibutton(pnl_ctrl, 'Position', [10, 10, 150, 28], ...
        'Text', '2. Session laden', ...
        'BackgroundColor', C.karte, 'FontColor', C.weiss, ...
        'ButtonPushedFcn', @(~,~) lade_zweite_session(tab, cfg));
    
    uilabel(pnl_ctrl, 'Position', [180, 45, 120, 18], ...
        'Text', 'Zeit-Offset S1 (s):', 'FontSize', 9, 'FontColor', C.grau, 'BackgroundColor', 'none');
    ef_offset1 = uieditfield(pnl_ctrl, 'numeric', ...
        'Position', [300, 43, 70, 22], 'Value', 0, ...
        'FontSize', 9, 'BackgroundColor', C.karte, 'FontColor', C.weiss);
    
    uilabel(pnl_ctrl, 'Position', [180, 15, 120, 18], ...
        'Text', 'Zeit-Offset S2 (s):', 'FontSize', 9, 'FontColor', C.grau, 'BackgroundColor', 'none');
    ef_offset2 = uieditfield(pnl_ctrl, 'numeric', ...
        'Position', [300, 13, 70, 22], 'Value', 0, ...
        'FontSize', 9, 'BackgroundColor', C.karte, 'FontColor', C.weiss);
    
    uibutton(pnl_ctrl, 'Position', [390, 10, 100, 28], ...
        'Text', 'Anwenden', ...
        'BackgroundColor', C.gruen, 'FontColor', C.weiss, ...
        'ButtonPushedFcn', @(~,~) update_vergleich(tab, signale, cfg, ef_offset1.Value, ef_offset2.Value));
    
    % Status
    lbl_status = uilabel(pnl_ctrl, 'Position', [510, 30, 400, 20], ...
        'Text', 'Keine 2. Session geladen', 'FontSize', 9, ...
        'FontColor', C.grau, 'BackgroundColor', 'none');
    
    % Speichere Handles im Tab UserData
    tab.UserData = struct('signale2', [], 'offset1', 0, 'offset2', 0, ...
        'lbl_status', lbl_status, 'cfg', cfg);

    % Initial-Plots mit nur einer Session
    erstelle_vergleichs_plots(tab, signale, [], cfg, 0, 0);
end

function lade_zweite_session(tab, cfg)
    % Laedt zweite MDF4-Datei
    [datei_name, datei_pfad] = uigetfile('*.mf4;*.MF4', '2. MDF4 Session auswaehlen');
    if isequal(datei_name, 0)
        return;
    end
    
    datei_pfad_voll = fullfile(datei_pfad, datei_name);
    try
        roh_daten = io.lade_mdf4(datei_pfad_voll, cfg);
        signale2 = extrahiere_signale(roh_daten, cfg);
        signale2 = berechne_abgeleitete(signale2, cfg);
        
        tab.UserData.signale2 = signale2;
        tab.UserData.lbl_status.Text = sprintf('Geladen: %s', datei_name);
        tab.UserData.lbl_status.FontColor = cfg.farben.gruen;
        
        % Auto-Update
        update_vergleich(tab, [], cfg, tab.UserData.offset1, tab.UserData.offset2);
    catch ME
        tab.UserData.lbl_status.Text = sprintf('Fehler: %s', ME.message);
        tab.UserData.lbl_status.FontColor = cfg.farben.rot;
    end
end

function update_vergleich(tab, signale, cfg, offset1, offset2)
    % Aktualisiert Vergleichs-Plots mit neuen Offsets
    if nargin < 4
        offset1 = 0;
        offset2 = 0;
    end
    
    tab.UserData.offset1 = offset1;
    tab.UserData.offset2 = offset2;
    
    % Loesche alte Plots
    delete(findall(tab, 'Type', 'uiaxes'));
    delete(findall(tab, 'Type', 'axes'));
    
    % Hole aktuelle Daten
    signale1 = signale;
    signale2 = tab.UserData.signale2;
    
    erstelle_vergleichs_plots(tab, signale1, signale2, cfg, offset1, offset2);
end

