headers = {'eFuse', 'I mon (A)', 'Error', 'Occurrence'};
for h = 1:4
    uilabel(pnl, 'Position', [5 + (h - 1) * col_w, position(4) - 36, col_w - 2, 16], ...
        'Text', headers{h}, 'FontSize', 8, 'FontWeight', 'bold', 'FontColor', C.rot, 'BackgroundColor', 'none');
