        try
            vals(i) = mean(abs(signale.(['P_mech_', rad]).Data)) / 1000;
            gefunden = true;
        catch
            % ignore
        end
    end
end

ax = uiaxes(pnl, 'Position', [5, 5, position(3) - 10, position(4) - 28]);
apply_rp_theme(ax, cfg);
if gefunden
    b = bar(ax, vals, 'FaceColor', 'flat');
