    set(ax, 'XTickLabel', upper(raeder), 'XTick', 1:numel(raeder));
    ylabel(ax, 'Ø Leistung (kW)', 'Color', C.grau, 'FontSize', 8);
else
    markiere_leer(ax, 'Mech. Leistung nicht verfuegbar', cfg);
end
end

