end

function plot_oder_leer(ax, signale, signal_namen, label, cfg, ist_abgeleitet)
% Plottet Signale oder zeigt "Keine Daten"
% Autor: [Benutzer]
% Datum: 2026-06-24

if nargin < 6
    ist_abgeleitet = false;
end

C = cfg.farben;
farben = {C.rot, C.rot_hell, C.orange, C.gruen, [0.4, 0.7, 1], [0.9, 0.9, 0.4], C.grau};
hold(ax, 'on');
n_geplottet = 0;
fehlende_label = {};

for i = 1:numel(signal_namen)
    sn = signal_namen{i};
    lbl = label{i};
    fn = tern_str(ist_abgeleitet, sn, signal_zu_feldname(sn));
    col = farben{mod(i - 1, numel(farben)) + 1};

    if isfield(signale, fn) && isfield(signale, [fn, '_ok']) && signale.([fn, '_ok'])
        try
            ts = signale.(fn);
            if isa(ts, 'timeseries') && ~isempty(ts.Data)
                d_vec = double(ts.Data);
                if size(d_vec, 2) > 1
                    d_vec = d_vec(:, 1);
                end
                plot(ax, ts.Time, d_vec, 'Color', col, 'LineWidth', 1.2, 'DisplayName', lbl);
                n_geplottet = n_geplottet + 1;
            elseif isnumeric(ts) && ~isempty(ts)
                fehlende_label{end + 1} = [lbl, ' (keine Zeitachse)'];
            else
                fehlende_label{end + 1} = lbl;
            end
        catch ME2
            fehlende_label{end + 1} = [lbl, ' (ERR: ', ME2.message(1:min(40, end)), ')'];
        end
    else
        fehlende_label{end + 1} = lbl;
    end
end

if n_geplottet > 0
    legend(ax, 'Location', 'best', 'TextColor', C.grau, ...
        'Color', [0.13, 0.13, 0.13], 'EdgeColor', C.grau2, 'FontSize', 8);
    xlabel(ax, 'Zeit (s)', 'Color', C.grau, 'FontSize', 8);
end

if ~isempty(fehlende_label)
    ylims = ylim(ax);
    xlims = xlim(ax);
    if n_geplottet == 0
        ax.Color = [0.11, 0.11, 0.11];
        text(ax, mean(xlims), mean(ylims), ...
            sprintf('KEINE DATEN\n%s', strjoin(fehlende_label, '\n')), ...
            'Color', C.fehlend, 'FontSize', 9, 'FontWeight', 'bold', ...
            'HorizontalAlignment', 'center', 'VerticalAlignment', 'middle');
    else
        text(ax, xlims(1), ylims(1), sprintf('Keine Daten: %s', strjoin(fehlende_label, ', ')), ...
            'Color', C.fehlend, 'FontSize', 8, ...
            'HorizontalAlignment', 'left', 'VerticalAlignment', 'bottom');
    end
end
hold(ax, 'off');
end

function plot_zellen_heatmap(ax, signale, modus, cfg)
% Plottet Zell-Spannungs- oder Temperatur-Heatmap
% Autor: [Benutzer]
% Datum: 2026-06-24

C = cfg.farben;
if strcmp(modus, 'voltage')
    prefix = 'ams_cell_voltage';
    n_zellen = cfg.ams.anzahl_zellen;
    n_zeilen = cfg.ams.heatmap_zeilen_v;
    n_spalten = cfg.ams.heatmap_spalten_v;
    einheit = 'V';
    clim_bereich = [3.5, 4.2];
else
    prefix = 'ams_cell_temp';
    n_zellen = cfg.ams.anzahl_temp_sensoren;
    n_zeilen = cfg.ams.heatmap_zeilen_t;
    n_spalten = cfg.ams.heatmap_spalten_t;
    einheit = '°C';
    clim_bereich = [20, 60];
end

daten = nan(n_zeilen, n_spalten);
n_gefunden = 0;
for i = 1:n_zellen
    r = floor((i - 1) / n_spalten) + 1;
    c = mod(i - 1, n_spalten) + 1;
    fn = signal_zu_feldname(sprintf('%s%03d_can', prefix, i));
    if isfield(signale, fn) && isfield(signale, [fn, '_ok']) && signale.([fn, '_ok'])
        try
            ts = signale.(fn);
            if isa(ts, 'timeseries')
                daten(r, c) = mean(ts.Data, 'omitnan');
            else
                daten(r, c) = mean(ts, 'omitnan');
            end
            n_gefunden = n_gefunden + 1;
        catch
            % ignore
        end
    end
end

if n_gefunden == 0
    util.markiere_leer(ax, sprintf('Keine Zell-%s Daten', einheit), cfg);
    return;
end

imagesc(ax, daten);
colormap(ax, 'hot');
clim(ax, clim_bereich);
cb = colorbar(ax);
cb.Color = C.grau;
cb.Label.String = einheit;
axis(ax, 'tight');
xlabel(ax, sprintf('Spalte  (%d/%d Zellen)', n_gefunden, n_zellen), 'Color', C.grau, 'FontSize', 8);
ylabel(ax, 'Reihe', 'Color', C.grau, 'FontSize', 8);
end

function str = letzter_bool_str(signale, feldname)
%LETZTER_BOOL_STR Gibt den letzten Bool-Wert als lesbaren String zurueck.
%
%   Eingabe:
%       signale  — Struct mit Signalen
%       feldname — String, Feldname des booleschen Signals
%
%   Ausgabe:
%       str      — 'ON' / 'OFF' oder '--' bei Fehler
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24

str = '--';

if ~isfield(signale, feldname)
    return;
end

daten = extrahiere_rohdaten(signale.(feldname));

if isempty(daten)
    return;
end

% Letzten gueltigen Wert holen (nicht NaN)
gueltige_idx = find(~isnan(daten), 1, 'last');

if isempty(gueltige_idx)
    return;
end

wert = daten(gueltige_idx);

% Logisch oder numerisch 0/1 auswerten
if islogical(wert) || wert ~= 0
    str = 'ON';
else
    str = 'OFF';
end
end

