function meta = parse_dateiname(datei_name, cfg)
% Parst Dateinamen nach Schema: Fahrzeug_YYYY-MM-DD_HH-MM-MM_Modus_Event.mf4
% Autor: [Benutzer]
% Datum: 2026-06-24
% Changelog: meta.modus initialisiert (Bugfix)

meta.dateiname = datei_name;
meta.fahrzeug = 'Unbekannt';
meta.datum = 'Unbekannt';
meta.zeit = '';
meta.event = 'Unbekannt';
meta.modus = 'Unbekannt';

tokens = regexp(datei_name, '^(.+?)_(\d{4}-\d{2}-\d{2})_(\d{2}-\d{2}-\d{2})_(.+?)_(.+?)\.mf4$', 'tokens', 'ignorecase');
if ~isempty(tokens)
    t = tokens{1};
    if numel(t) >= 5
        meta.fahrzeug = t{1};
        meta.datum = t{2};
        meta.zeit = strrep(t{3}, '-', ':');
        meta.modus = t{4};
        meta.event = strrep(t{5}, '_', ' ');
    end
end
end

function ts_out = sicheres_resample(ts_in, t_ref)
% Sicheres resample mit Extrapolation
% Autor: [Benutzer]
% Datum: 2026-06-24

try
    ts_out = resample(ts_in, t_ref);
catch
    % Manuelle Interpolation mit Extrapolation
    t_in = ts_in.Time;
    d_in = double(ts_in.Data);
    if size(d_in, 2) > 1
        d_in = d_in(:, 1);
    end
    d_out = interp1(t_in, d_in, t_ref, 'linear', 'extrap');
    ts_out = timeseries(d_out, t_ref, 'Name', ts_in.Name);
end
end

