function daten = extrahiere_rohdaten(roh)
%EXTRAHIERE_ROHDATEN Normalisiert Signal-Rohdaten zu einem numerischen Array.
%
%   Unterstuetzt:
%       - timeseries  → .Data
%       - Struct .Data → .Data
%       - Numerisch   → direkt
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24

if isa(roh, 'timeseries')
    daten = roh.Data;
elseif isstruct(roh) && isfield(roh, 'Data')
    daten = roh.Data;
elseif isnumeric(roh) || islogical(roh)
    daten = roh;
else
    daten = [];
end

% Sicherstellen dass es ein Spaltenvektor oder Array ist
if ~isempty(daten) && isvector(daten)
    daten = daten(:);
end
end

function signale = extrahiere_signale(roh_daten, cfg)
% Extrahiert definierte Signale aus MDF4-Rohdaten
% Autor: [Benutzer]
% Datum: 2026-06-24

signal_namen = get_signal_liste(cfg);
n_gefunden = 0;

fprintf('  Durchsuche %d Cell-Gruppen nach Signalen...\n', numel(roh_daten.daten));

lookup = containers.Map('KeyType', 'char', 'ValueType', 'any');
for ci = 1:numel(roh_daten.daten)
    tt = roh_daten.daten{ci};
    if ~isa(tt, 'timetable')
        continue;
    end
    spalten = tt.Properties.VariableNames;
    for k = 1:numel(spalten)
        if ~isKey(lookup, spalten{k})
            lookup(spalten{k}) = struct('cell_idx', ci, 'col_name', spalten{k});
        end
    end
end
fprintf('  Lookup fertig: %d eindeutige Spaltennamen.\n', lookup.Count);

for i = 1:numel(signal_namen)
    signal_name = signal_namen{i};
    feld_name = signal_zu_feldname(signal_name);

    if isKey(lookup, signal_name)
        info = lookup(signal_name);
        ci = info.cell_idx;
        col_name = info.col_name;
        try
            tt = roh_daten.daten{ci};
            t_roh = tt.Properties.RowTimes;

            if isa(t_roh, 'duration')
                t_sec = seconds(t_roh - t_roh(1));
            elseif isa(t_roh, 'datetime')
                t_sec = seconds(t_roh - t_roh(1));
            else
                t_sec = double(t_roh) - double(t_roh(1));
            end

            werte = tt.(col_name);
            if ~isa(werte, 'double')
                werte = double(werte);
            end
            if size(werte, 2) > 1
                werte = werte(:, 1);
            end

            signale.(feld_name) = timeseries(werte, t_sec, 'Name', signal_name);
            signale.([feld_name '_ok']) = true;
            n_gefunden = n_gefunden + 1;
        catch ME
            signale.(feld_name) = [];
            signale.([feld_name '_ok']) = false;
            if n_gefunden == 0 && i <= 5
                fprintf('  [ERR] %s: %s\n', signal_name, ME.message);
            end
        end
    else
        signale.(feld_name) = [];
        signale.([feld_name '_ok']) = false;
    end
end

fprintf('  Signale erfolgreich geladen: %d / %d\n', n_gefunden, numel(signal_namen));

% Debug-Ausgabe speed_can
fn_test = 'speed_can';
if isfield(signale, fn_test)
    fprintf('  [DEBUG] speed_can Feld vorhanden, _ok=%d\n', signale.([fn_test '_ok']));
    if signale.([fn_test '_ok'])
        fprintf('  [DEBUG] speed_can: %d Punkte, max=%.2f\n', numel(signale.(fn_test).Data), max(signale.(fn_test).Data));
    end
else
    fprintf('  [DEBUG] speed_can NICHT als Feld in signale vorhanden!\n');
end

% Zeitbasis finden
signale.t_base = [];
signale.t_base_ok = false;
for i = 1:numel(signal_namen)
    fn = signal_zu_feldname(signal_namen{i});
    if isfield(signale, [fn '_ok']) && signale.([fn '_ok'])
        try
            signale.t_base = signale.(fn).Time;
            signale.t_base_ok = true;
            break;
        catch
            % continue
        end
    end
end
end

function wert_str = feld_wert_str(signale, feldname, ok_feldname, fallback, modus)
%FELD_WERT_STR Gibt einen formatierten Wert aus einem Signal-Struct zurück.
%
%   Eingabe:
%       signale      — Struct mit Signalen und OK-Flags
%       feldname     — String, Feldname des Hauptsignals
%       ok_feldname  — String, Feldname des OK-Flags (optional, '' wenn nicht benötigt)
%       fallback     — Wert/String, falls Signal ungültig
%       modus        — String, optional:
%                      'mean_data' → Mittelwert über alle Datenpunkte
%                      '' oder fehlend → letzter Wert
%
%   Ausgabe:
%       wert_str     — Formatierter Wert als String/Double
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24

    arguments
        signale
        feldname (1, :) char
        ok_feldname (1, :) char = ''
        fallback = '--'
        modus (1, :) char = ''
    end

    % Pruefen ob OK-Flag existiert und false ist
    if ~isempty(ok_feldname) && isfield(signale, ok_feldname)
        ok_wert = signale.(ok_feldname);
        if islogical(ok_wert) && ~ok_wert
            wert_str = fallback;
            return;
        end
        if isnumeric(ok_wert) && ok_wert == 0
            wert_str = fallback;
            return;
        end
    end

    % Pruefen ob Hauptfeld existiert
    if ~isfield(signale, feldname)
        wert_str = fallback;
        return;
    end

    daten = signale.(feldname);
    daten = extrahiere_rohdaten(daten);

    if isempty(daten) || ~isnumeric(daten) || all(isnan(daten))
        wert_str = fallback;
        return;
    end

    % Modus auswerten
    if strcmp(modus, 'mean_data')
        wert = mean(daten, 'omitnan');
    else
        gueltige_idx = find(~isnan(daten), 1, 'last');
        if isempty(gueltige_idx)
            wert_str = fallback;
            return;
        end
        wert = daten(gueltige_idx);
    end

    wert_str = wert;
end

function max_wert = signal_max_wert(signale, feldname, fallback)
%SIGNAL_MAX_WERT Gibt den maximalen Wert eines Signals zurück.
%
%   Eingabe:
%       signale  — Struct mit Signalen (timeseries oder numerisch)
%       feldname — String, Feldname des Signals
%       fallback — Wert, falls Signal fehlt oder leer
%
%   Ausgabe:
%       max_wert — Numerischer Maximalwert oder fallback
%
%   Autor:  [Benutzer]
%   Datum:  2026-06-24

    if ~isfield(signale, feldname)
        max_wert = fallback;
        return;
    end

    daten = signale.(feldname);
    daten = extrahiere_rohdaten(daten);

    if isempty(daten) || ~isnumeric(daten) || all(isnan(daten))
        max_wert = fallback;
        return;
    end

    max_wert = max(daten, [], 'omitnan');
end

function feldname = signal_zu_feldname(signal_name)
% Wandelt Signalnamen in gueltige MATLAB-Feldnamen um
% Autor: [Benutzer]
% Datum: 2026-06-24

feldname = regexprep(signal_name, '[^a-zA-Z0-9_]', '_');
if ~isempty(feldname) && ~isletter(feldname(1))
    feldname = ['sig_', feldname];
end
end
